package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.graphics.Typeface;
import android.widget.*;
import org.json.*;
/** Account home with genuine summaries and recent library snapshots, not a simulated feed. */
final class DashboardView extends ScrollView {
 private final LinearLayout body,content,heroContent,feedback;private final TextView state;private final Button refresh;private boolean loading,loaded;
 private final Runnable gamesTab,mediaTab,steamTab,retroTab;
 private final NativePresence presence;private final LinearLayout online;private JSONArray friends=new JSONArray();private TextView journey,friendsCount;private ProgressBar xpBar;private JSONObject peers=new JSONObject();private boolean active,socialBusy,presenceConnected;private final android.os.Handler timer=new android.os.Handler();
 private final NativePresence.Listener listener=(value,connected)->{peers=value;presenceConnected=connected;renderOnline(connected);};
 private final Runnable tick=new Runnable(){public void run(){if(!active)return;loadSocial();timer.postDelayed(this,45000);}};
 void setForeground(boolean value){if(active==value)return;active=value;timer.removeCallbacks(tick);if(value){presence.listen(listener);tick.run();}else presence.remove(listener);}
 @Override protected void onDetachedFromWindow(){setForeground(false);super.onDetachedFromWindow();}
 private void loadSocial(){if(socialBusy)return;socialBusy=true;new AccountRepository(getContext()).socialHome((rows,error)->{socialBusy=false;if(!active)return;if(error!=null){online.removeAllViews();online.addView(text(error,13,0xffb7a6ff));return;}JSONObject data=rows.optJSONObject(0);friends=data.optJSONArray("friends");if(friends==null)friends=new JSONArray();renderOnline(presenceConnected);});}

 private static String steamCover(JSONObject game){String cover=game.optString("cover","");String app=game.optString("appid","");if((cover.isEmpty()||cover.equals("null"))&&app.matches("[0-9]{1,12}"))return "https://cdn.cloudflare.steamstatic.com/steam/apps/"+app+"/header.jpg";return cover;}
 private void renderOnline(boolean connected){if(online==null)return;online.removeAllViews();online.addView(text("Amigos online · "+friends.length()+" na sua lista",17,0xffe9e4f2));int count=0;if(connected)for(int i=0;i<friends.length();i++){JSONObject friend=friends.optJSONObject(i);if(friend==null||"invisivel".equals(friend.optString("status_personalizado")))continue;JSONObject peer=peers.optJSONObject(friend.optString("id")),meta=peer==null?null:PeerActivity.current(peer.optJSONArray("metas"),System.currentTimeMillis());if(meta==null||"invisivel".equals(meta.optString("status")))continue;count++;LinearLayout friendCard=FriendHomeCard.create(getContext(),friend.optString("nome"),PeerActivity.label(meta),friend.optString("avatar_url"),"",true);int statusIndex=ProfileStatus.index(meta.optString("status","online"));((TextView)((LinearLayout)friendCard.getChildAt(1)).getChildAt(1)).setTextColor(ProfileStatus.COLORS[statusIndex]);friendCard.setContentDescription(friend.optString("nome")+" · "+PeerActivity.label(meta));online.addView(friendCard);}if(count==0)online.addView(text(connected?"Nenhum amigo online neste momento.":"Conectando presença…",13,0xff9ca9b8));}


 DashboardView(Context c,Runnable games,Runnable media,Runnable steam,Runnable retro,NativePresence live){super(c);presence=live;gamesTab=games;mediaTab=media;steamTab=steam;retroTab=retro;setFillViewport(true);setVerticalScrollBarEnabled(false);body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(18),dp(16),dp(18),dp(24));addView(body);
  state=text("Preparando sua BatCaverna…",13,0xff9ca9b8);body.addView(state);feedback=new LinearLayout(c);feedback.setOrientation(LinearLayout.VERTICAL);body.addView(feedback);heroContent=new LinearLayout(c);heroContent.setOrientation(LinearLayout.VERTICAL);body.addView(heroContent);content=new LinearLayout(c);content.setOrientation(LinearLayout.VERTICAL);online=new LinearLayout(c);online.setOrientation(LinearLayout.VERTICAL);body.addView(content);body.addView(online);
  refresh=new Button(c);refresh.setText("Atualizar início");AppStyle.button(refresh,false);refresh.setOnClickListener(v->load());body.addView(refresh);load();
 }
 private void load(){if(loading)return;loading=true;refresh.setEnabled(false);state.setVisibility(GONE);feedback.removeAllViews();if(!loaded)feedback.addView(ScreenState.loading(getContext(),"Preparando sua BatCaverna…",2,false));new AccountRepository(getContext()).dashboard((rows,error)->{loading=false;refresh.setEnabled(true);JSONObject data=rows==null?null:rows.optJSONObject(0);if(error!=null||data==null){feedback.removeAllViews();feedback.addView(ScreenState.message(getContext(),true,"Não foi possível carregar o início",error!=null?error:"O resumo da sua conta está indisponível no momento.","Tentar novamente",()->load()));return;}loaded=true;feedback.removeAllViews();state.setVisibility(VISIBLE);render(data);});}
 private void render(JSONObject data){if(data==null){state.setText("Resumo indisponível. Tente atualizar.");return;}content.removeAllViews();heroContent.removeAllViews();state.setText("SEU ESPAÇO · SUAS CONQUISTAS");
  JSONObject profile=data.optJSONObject("profile");DashboardBanner banner=new DashboardBanner(getContext(),profile,gamesTab);heroContent.addView(banner);journey=banner.level;xpBar=banner.progress;new AccountRepository(getContext()).ranking((rows,e)->{if(e!=null){journey.setText("Seu espaço de jogos e histórias");return;}String user=SessionPreferences.get(getContext()).getString("user_id","");for(int i=0;i<rows.length();i++){JSONObject me=rows.optJSONObject(i);if(user.equals(me.optString("id"))){long xp=me.optLong("xp");journey.setText(ProfileProgress.title(ProfileProgress.level(xp))+" • Nível "+ProfileProgress.level(xp)+"\n"+xp+" XP • "+(ProfileProgress.next(xp)-xp)+" para o próximo");xpBar.setProgress(ProfileProgress.percentage(xp));xpBar.setContentDescription("Progresso para o próximo nível: "+ProfileProgress.percentage(xp)+"%");xpBar.setVisibility(VISIBLE);break;}}});
  heroContent.addView(DashboardMetrics.create(getContext(),data,gamesTab,mediaTab));
  LinearLayout progress=card();progress.addView(text("Sua jornada nos jogos",17,0xfff3f4f8));int total=data.optInt("total"),done=data.optInt("finished");int percent=total==0?0:Math.min(100,Math.max(0,(int)(100L*done/total)));progress.addView(text(done+" de "+total+" finalizados • "+percent+"%",13,0xff9ca9b8));ProgressBar bar=new ProgressBar(getContext(),null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress(percent);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff9473ee));progress.addView(bar,new LinearLayout.LayoutParams(-1,dp(8)));content.addView(progress);
  JSONArray resume=new JSONArray();for(String key:new String[]{"games","movies"}){JSONArray rows=data.optJSONArray(key);for(int i=0;rows!=null&&i<rows.length();i++)resume.put(rows.optJSONObject(i));}
  AccountRepository repo=new AccountRepository(getContext());
  content.addView(new HomeResumeView(getContext(),resume,new HomeResumeView.Actions(){
   public void details(JSONObject item,Button button){openResume(item,!"jogos".equals(item.optString("categoria")),button);}
   public void progress(JSONObject item,AccountRepository.Callback cb){try{repo.journey("progress",new JSONObject().put("item_id",item.optString("id")),cb);}catch(JSONException e){cb.done(null,"Progresso indisponível.");}}
   public void episodes(JSONObject item,Runnable saved){JourneySheet.progress(getContext(),item.optString("id"),saved);}
   public void status(JSONObject item,String status,AccountRepository.Callback cb){repo.updateHomeStatus(item,status,cb);}
   public void explore(String kind){if("refresh".equals(kind))load();else if("all".equals(kind)||"jogos".equals(kind))gamesTab.run();else mediaTab.run();}
  }));
  retroSummary();

  TextView updatesTitle=text("Recentes na biblioteca",17,0xffe9e4f2);updatesTitle.setTypeface(null,Typeface.BOLD);content.addView(updatesTitle);JSONArray updates=data.optJSONArray("updates");LinearLayout timeline=card();if(updates==null||updates.length()==0)timeline.addView(text("Nenhum título cadastrado ainda.",14,0xff9ca9b8));else for(int i=0;i<updates.length();i++){JSONObject item=updates.optJSONObject(i);if(item==null)continue;TextView t=text(item.optString("nome","Título"),15,0xfff3f4f8);t.setTypeface(null,Typeface.BOLD);timeline.addView(t);timeline.addView(text(("filmes".equals(item.optString("categoria"))?"Filmes e séries":"Jogos")+" • "+item.optString("status",""),12,0xff9ca9b8));}content.addView(timeline);
  Button steam=new Button(getContext());steam.setText("Explorar minha Steam");AppStyle.button(steam,false);steam.setOnClickListener(v->steamTab.run());content.addView(steam);
 }
 private void openResume(JSONObject item,boolean media,Button button){button.setEnabled(false);new AccountRepository(getContext()).details(item,(rows,error)->{button.setEnabled(true);if(error!=null){Toast.makeText(getContext(),error,Toast.LENGTH_LONG).show();return;}TitleDetailsDialog.show(getContext(),rows.optJSONObject(0),media,(updated,deleted)->load());});}
 private void retroSummary(){LinearLayout slot=card();slot.addView(text("Meu Retrô",17,0xfff3f4f8));TextView summary=text("Consultando sua jornada retrô…",13,0xff9ca9b8);slot.addView(summary);Button open=new Button(getContext());open.setText("Continuar no Meu Retrô");AppStyle.button(open,false);slot.addView(open);open.setOnClickListener(v->retroTab.run());content.addView(slot);new AccountRepository(getContext()).retro((rows,error)->{if(error!=null){summary.setText("Abra Meu Retrô para consultar sua coleção.");return;}JSONObject data=rows==null?null:rows.optJSONObject(0);JSONArray games=data==null?null:data.optJSONArray("jogos");JSONObject collection=data==null?null:data.optJSONObject("collection");java.util.Map<String,java.util.List<JSONObject>> groups=RetroLibraryPolicy.groups(games,collection==null?null:collection.optJSONObject("statuses"),"");java.util.List<JSONObject> active=groups.get("progress");if(active==null||active.isEmpty()){summary.setText("Nenhum clássico em andamento. Explore sua coleção.");return;}JSONObject game=active.get(0);summary.setText(game.optString("nome")+" · "+game.optInt("desbloqueadas")+"/"+game.optInt("total")+" conquistas\n"+active.size()+" jogos em andamento");});}
 private LinearLayout card(){LinearLayout v=new LinearLayout(getContext());v.setOrientation(LinearLayout.VERTICAL);v.setPadding(dp(14),dp(12),dp(14),dp(12));v.setBackground(AppStyle.surface(v,NativeTheme.panelDark(getContext()),20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(8),0,dp(12));v.setLayoutParams(p);return v;}
 private TextView text(String s,int size,int color){TextView v=new TextView(getContext());v.setText(s);v.setTextSize(size);v.setTextColor(NativeTheme.textColor(v.getContext(),color));v.setPadding(0,dp(4),0,dp(4));return v;}
 private int dp(int n){return AppStyle.dp(this,n);}
}
